#include "CloseToHSL/Core/Virtualization/Compatibility/Frontend/Decode/YAKSys_Hybrid_CPU.Core.VmxCompatDecodeBoundary.h"
#include "CloseToHSL/Core/Virtualization/Compatibility/Frontend/Decode/VmxFrozenOpcodeValues.h"
#include <cassert>
using namespace YAKSys_Hybrid_CPU::Core;
using namespace YAKSys_Hybrid_CPU::Core::VmxFrozenOpcodeValues;
int main(){ VmxCompatDecodeBoundary b; auto req=[](unsigned short op,bool d,bool c,bool s,bool n){return std::make_shared<VmxCompatDecodeRequest>(op,1,2,3,d,c,s,n);}; assert(b.Decode(req(260,true,true,true,true))->Decision==VmxCompatDecodeDecision::UnknownOpcode); assert(b.Decode(req(VMREAD,false,true,true,true))->Decision==VmxCompatDecodeDecision::DescriptorValidationDenied); assert(b.Decode(req(VMREAD,true,false,true,true))->Decision==VmxCompatDecodeDecision::CapabilityValidationDenied); assert(b.Decode(req(VMREAD,true,true,false,true))->Decision==VmxCompatDecodeDecision::SchedulingValidationDenied); assert(b.Decode(req(VMREAD,true,true,true,false))->Decision==VmxCompatDecodeDecision::NoEmissionValidationDenied); auto r=b.Decode(req(INVEPT,true,true,true,true)); assert(r->IsAllowed && r->Payload->OperandForm==Vmx::VmxOperandForm::InvalidationScopeAndDescriptor && r->Payload->InvalidationScope==VmxInvalidationScope::AllContexts && r->Payload->ExitQualification.Encode()==0x300020000ULL); auto vmxon=b.Decode(req(VMXON,true,true,true,true)); assert(vmxon->Payload->RootDescriptor.Address==2 && vmxon->Payload->RootDescriptor.isExplicit()); auto fn=VmxInstructionPayload::FromDecodedRegisters(VMFUNC,0,7,9); assert(fn->FunctionLeaf==VmxFunctionLeaf::Lane7QueryCaps); }
